(()=>{
 const $=s=>document.querySelector(s),money=c=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:2}).format(c/100);
 function sinceLabel(value){if(!value)return 'Active supporter';const since=new Date(value),now=new Date();if(!Number.isFinite(since.getTime()))return 'Active supporter';let months=(now.getUTCFullYear()-since.getUTCFullYear())*12+now.getUTCMonth()-since.getUTCMonth();if(now.getUTCDate()<since.getUTCDate())months--;return months<1?'Supporting for less than a month':`Supporting for ${months} ${months===1?'month':'months'}`;}
 function donorRow(d){const row=document.createElement('article');row.className='donor';const avatar=document.createElement('span');avatar.className='donor-avatar';avatar.setAttribute('aria-hidden','true');avatar.textContent=d.name.slice(0,2).toUpperCase();if(d.avatarUrl){const img=document.createElement('img');img.src=d.avatarUrl;img.alt='';img.loading='lazy';img.referrerPolicy='no-referrer';img.addEventListener('error',()=>{avatar.textContent=d.name.slice(0,2).toUpperCase();});avatar.replaceChildren(img);}const details=document.createElement('div');details.className='donor-details';const name=document.createElement('strong');name.className='donor-name';name.textContent=d.name;const history=document.createElement('span');history.className='donor-history';history.textContent=d.history||sinceLabel(d.supportingSince);details.append(name,history);row.append(avatar,details);if(d.monthlyCents!==null&&d.monthlyCents!==undefined){const amount=document.createElement('span');amount.className='donor-amount';amount.textContent=money(d.monthlyCents)+' / mo';row.append(amount);}return row;}
 async function load(){ $('#retryDonations').hidden=true;try{const response=await fetch('/api/donations',{cache:'no-store'});if(!response.ok)throw Error();const data=await response.json(),f=data.funding;
 $('#goalAmount').textContent=money(data.goalCents);$('#costTotal').textContent=money(data.goalCents);$('#fundingProgress').max=data.goalCents;
 const available=f.monthlyCents!==null;$('#fundingAmount').textContent=available?money(f.monthlyCents):(f.status==='not_configured'?'Not connected':'Unavailable');$('#fundingAmount').classList.toggle('unavailable',!available);
 $('#fundingProgress').value=available?Math.min(f.monthlyCents,data.goalCents):0;$('#fundingProgress').setAttribute('aria-valuetext',available?money(f.monthlyCents)+' of '+money(data.goalCents):'Funding data unavailable');
 const messages={not_configured:'',awaiting_sync:'Waiting for the first Patreon update.',unavailable:'Patreon totals are temporarily unavailable.',stale:'Last known totals · Patreon update delayed.',incomplete:'Some billing amounts are unavailable. Total is not shown.'};
 $('#fundingMessage').textContent=messages[f.status]??(f.monthlyCents>=data.goalCents?'Monthly goal covered. Thank you!':money(data.goalCents-f.monthlyCents)+' to reach our monthly goal');
 $('#updatedAt').textContent=f.checkedAt?'Updated '+new Date(f.checkedAt).toLocaleString([], {month:'short',day:'numeric',hour:'numeric',minute:'2-digit'}):'';
 $('#supporterCount').textContent=f.checkedAt?String(f.supporterCount):'';const list=$('#donorList');list.replaceChildren();for(const donor of f.donors)list.append(donorRow(donor));if(f.anonymousCount)list.append(donorRow({name:f.anonymousCount===1?'Anonymous supporter':f.anonymousCount+' anonymous supporters',history:'Thank you for your support.'}));
 if(!list.children.length){const empty=document.createElement('p');empty.className='empty-state';empty.textContent=f.checkedAt?'No active paid supporters to show yet.':'Supporters will appear once Patreon is connected.';list.append(empty);}
 const rows=$('#costRows');rows.replaceChildren();for(const cost of data.costs){const row=document.createElement('tr'),name=document.createElement('th'),amount=document.createElement('td');name.scope='row';name.textContent=cost.name;amount.textContent=money(cost.monthlyCents);row.append(name,amount);rows.append(row);}
 }catch{$('#fundingAmount').textContent='Unavailable';$('#fundingAmount').classList.add('unavailable');$('#fundingProgress').value=0;$('#fundingProgress').setAttribute('aria-valuetext','Funding data unavailable');$('#updatedAt').textContent='';$('#supporterCount').textContent='';$('#fundingMessage').textContent='Donation information could not be loaded.';$('#donorList').textContent='Supporters are temporarily unavailable.';$('#retryDonations').hidden=false;}}
 $('#retryDonations').addEventListener('click',load);window.addEventListener('pageshow',e=>{if(e.persisted)load();});load();
})();
